@page "/board"
@namespace sv_de963ff7b932439c8c4fde73ab5cc393.Components.Pages.Board
@using sv_de963ff7b932439c8c4fde73ab5cc393.Components.Pages.Board
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error-message">Error: @errorMessage</p>
}
else
{
    <div class="board-stats">
        <span><strong>Total:</strong> @allTasks.Count</span>
        <span><strong>To Do:</strong> @todoTasks.Count</span>
        <span><strong>In Progress:</strong> @inProgressTasks.Count</span>
        <span><strong>Done:</strong> @doneTasks.Count</span>
        <span><strong>Overdue:</strong> @overdueTasks.Count</span>
    </div>

    <div class="board-search">
        <input type="text" placeholder="Search tasks by title..." @bind="searchText" @bind:event="oninput" />
    </div>

    <div class="kanban-board">
        <KanbanColumn Title="To Do"
                      Tasks="filteredTodo"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRight="task => MoveTask(task, \"In Progress\")"
                      OnAddTask="formData => AddTask(formData, \"To Do\")" />

        <KanbanColumn Title="In Progress"
                      Tasks="filteredInProgress"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeft="task => MoveTask(task, \"To Do\")"
                      OnMoveRight="task => MoveTask(task, \"Done\")"
                      OnAddTask="formData => AddTask(formData, \"In Progress\")" />

        <KanbanColumn Title="Done"
                      Tasks="filteredDone"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="task => MoveTask(task, \"In Progress\")"
                      OnAddTask="formData => AddTask(formData, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private string? errorMessage;
    private string searchText = string.Empty;

    private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == "Done").ToList();
    private List<TaskItem> overdueTasks => allTasks.Where(t => t.DueDate < DateTime.Today).ToList();

    private List<TaskItem> filteredTodo => FilterBySearch(todoTasks);
    private List<TaskItem> filteredInProgress => FilterBySearch(inProgressTasks);
    private List<TaskItem> filteredDone => FilterBySearch(doneTasks);

    private List<TaskItem> FilterBySearch(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;
        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) formData, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
            // The service returns the task; ensure it has the correct status
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }
}

.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 0.95rem;
}

.kanban-board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.kanban-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    min-width: 250px;
}

.column-header h3 {
    margin: 0 0 0.75rem 0;
    font-size: 1.1rem;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 100px;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-title {
    margin: 0 0 0.25rem 0;
    font-size: 0.95rem;
}

.task-assignee {
    margin: 0 0 0.5rem 0;
    font-size: 0.85rem;
    color: #6c757d;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

.priority-high {
    background: #f8d7da;
    color: #842029;
}

.priority-medium {
    background: #fff3cd;
    color: #664d03;
}

.priority-low {
    background: #d1e7dd;
    color: #0f5132;
}

.task-due-date {
    font-size: 0.8rem;
    color: #6c757d;
}

.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    padding: 0.25rem 0.5rem;
    font-size: 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

.column-footer {
    margin-top: 0.75rem;
}

.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 1px dashed #adb5bd;
    border-radius: 6px;
    background: transparent;
    cursor: pointer;
    color: #6c757d;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    background: #fff;
    padding: 0.75rem;
    border-radius: 6px;
    border: 1px solid #dee2e6;
}

.add-task-form input,
.add-task-form select {
    padding: 0.4rem 0.6rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.85rem;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save {
    padding: 0.4rem 0.75rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-cancel {
    padding: 0.4rem 0.75rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.loading-message,
.error-message {
    padding: 1rem;
    font-size: 1rem;
}

.error-message {
    color: #dc3545;
}

