@page "/board"
@namespace sv_de963ff7b932439c8c4fde73ab5cc393.Components.Pages.Board
@using sv_de963ff7b932439c8c4fde73ab5cc393.Components.Pages.Board
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error-message">Error: @errorMessage</p>
}
else
{
    <div class="board-stats">
        <span><strong>Total:</strong> @allTasks.Count</span>
        <span><strong>To Do:</strong> @todoTasks.Count</span>
        <span><strong>In Progress:</strong> @inProgressTasks.Count</span>
        <span><strong>Done:</strong> @doneTasks.Count</span>
        <span><strong>Overdue:</strong> @overdueTasks.Count</span>
    </div>

    <div class="board-search">
        <input type="text" placeholder="Search tasks by title..." @bind="searchText" @bind:event="oninput" />
    </div>

    <div class="kanban-board">
        <KanbanColumn Title="To Do"
                      Tasks="filteredTodo"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRight="task => MoveTask(task, \"In Progress\")"
                      OnAddTask="formData => AddTask(formData, \"To Do\")" />

        <KanbanColumn Title="In Progress"
                      Tasks="filteredInProgress"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeft="task => MoveTask(task, \"To Do\")"
                      OnMoveRight="task => MoveTask(task, \"Done\")"
                      OnAddTask="formData => AddTask(formData, \"In Progress\")" />

        <KanbanColumn Title="Done"
                      Tasks="filteredDone"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="task => MoveTask(task, \"In Progress\")"
                      OnAddTask="formData => AddTask(formData, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private string? errorMessage;
    private string searchText = string.Empty;

    private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == "Done").ToList();
    private List<TaskItem> overdueTasks => allTasks.Where(t => t.DueDate < DateTime.Today).ToList();

    private List<TaskItem> filteredTodo => FilterBySearch(todoTasks);
    private List<TaskItem> filteredInProgress => FilterBySearch(inProgressTasks);
    private List<TaskItem> filteredDone => FilterBySearch(doneTasks);

    private List<TaskItem> FilterBySearch(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;
        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) formData, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
            // The service returns the task; ensure it has the correct status
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }
}

